// Bounds of a geometry. A row with no position (a CSV row without coordinates) has geometry null.
export function boundsOf(geometry) {
  const points = geometry?.points ?? [];
  if (points.length === 0) return [NaN, NaN, NaN, NaN];
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const [x, y] of points) {
    minX = Math.min(minX, x);
    minY = Math.min(minY, y);
    maxX = Math.max(maxX, x);
    maxY = Math.max(maxY, y);
  }
  return [minX, minY, maxX, maxY];
}

export function encodeGeometry(geometry) {
  return geometry ? JSON.stringify(geometry) : null;
}

