import { test } from 'node:test';
import assert from 'node:assert/strict';
import { writeFeatures } from '../src/gpkg-writer.js';

function fakeDb() {
  const tables = { features: [], rtree: [] };
  return {
    tables,
    prepare: (sql) => ({ run: (...row) => (sql.includes('rtree_') ? tables.rtree : tables.features).push(row) }),
  };
}

test('a row with no position is written but left out of the index and the extent', () => {
  const db = fakeDb();
  const extent = writeFeatures(db, 'storms', [
    { id: 1, geometry: { points: [[10, 20]] } },
    { id: 2, geometry: null },
    { id: 3, geometry: { points: [[12, 18]] } },
  ]);
  assert.equal(db.tables.features.length, 3);
  assert.deepEqual(db.tables.rtree.map((row) => row[0]), [1, 3]);
  assert.deepEqual(extent, [10, 18, 12, 20]);
});

test('a layer with no position at all has no extent', () => {
  const db = fakeDb();
  assert.equal(writeFeatures(db, 'notes', [{ id: 1, geometry: null }]), null);
  assert.equal(db.tables.rtree.length, 0);
});
